javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let authorList = api.state.authorList;
    let eventList = event.payload.value;

    let authorNames = authorList.map(user => user.userName);
    let eventNames = eventList.map(user => user.label);

    for (let author in eventNames) {
        if (!(authorNames.includes(eventNames[author]))) {
            let userDetailsToAdd = eventList[author];
            let obj = {
                "userName": "",
                "imageSrc": "",
                "id": "",
            };
            obj.userName = userDetailsToAdd.label;
            obj.id = userDetailsToAdd.id;
            obj.imageSrc = userDetailsToAdd.avatarProps.imageSrc;
            authorList.push(obj);
        }
    }
    for (let user in authorNames) {
        if (!(eventNames.includes(authorNames[user]))) {
            authorList.splice(user, 1);
        }
    }
    return {
        propName: 'authorList',
        value: authorList
    };
})

