    api,
    event
}) {
    let updatedEvent = JSON.parse(JSON.stringify(event.context.item.value));
    if (updatedEvent.isHidden) {
        updatedEvent.isHidden = false;
    } else {
        updatedEvent.isHidden = true;
    }
    let timelineEvents = api.state.rawTimelineEvents;
    for (let index = 0; index < timelineEvents.length; index++) {
